        ByteBuffer buffer = MemoryUtil.memByteBuffer(MemoryUtil.nmemAlloc(data.length), data.length);
        for (int i = 0; i < data.length; i++) buffer.put(i, data[i]);
        buffer.position(0);
        System.out.println("Result: " + getStringList(buffer));
        MemoryUtil.nmemFree(MemoryUtil.memAddress0(buffer));
    }
}
