public class TestDecode3 {
    public static void main(String[] args) {
        boolean ok = true;

        // --- UTF8 with non-zero position (ALUtil.getStringList style) ---
        byte[] utf8 = ("Hello\0World\0\0").getBytes(StandardCharsets.UTF_8);
        ByteBuffer b = MemoryUtil.memByteBuffer(MemoryUtil.nmemAlloc(utf8.length), utf8.length);
        for (int i = 0; i < utf8.length; i++) b.put(i, utf8[i]);
        b.position(0);
        // scan: read past "Hello\0"
        while (b.get() != 0) { /* skip */ }
        int limit = b.position() - 1; // "Hello" ends at limit (index 5)
        String s1 = MemoryUtil.memUTF8(b, limit - 0, 0);
        System.out.println("UTF8[0] = " + s1);
        ok &= s1.equals("Hello");
        int offset = b.position(); // 6
        while (b.get() != 0) { /* skip */ }
        limit = b.position() - 1;
        String s2 = MemoryUtil.memUTF8(b, limit - offset, offset);
        System.out.println("UTF8[1] = " + s2);
        ok &= s2.equals("World");
        MemoryUtil.nmemFree(MemoryUtil.memAddress0(b));

        // --- ASCII with non-zero position ---
        byte[] ascii = ("DeviceA\0DeviceB\0\0").getBytes(StandardCharsets.ISO_8859_1);
        ByteBuffer a = MemoryUtil.memByteBuffer(MemoryUtil.nmemAlloc(ascii.length), ascii.length);
        for (int i = 0; i < ascii.length; i++) a.put(i, ascii[i]);
        a.position(0);
        while (a.get() != 0) { /* skip */ }
        limit = a.position() - 1;
        String a1 = MemoryUtil.memASCII(a, limit - 0, 0);
        System.out.println("ASCII[0] = " + a1);
        ok &= a1.equals("DeviceA");
        offset = a.position();
        while (a.get() != 0) { /* skip */ }
        limit = a.position() - 1;
        String a2 = MemoryUtil.memASCII(a, limit - offset, offset);
        System.out.println("ASCII[1] = " + a2);
        ok &= a2.equals("DeviceB");
        MemoryUtil.nmemFree(MemoryUtil.memAddress0(a));

        // --- UTF16 with non-zero position ---
        char[] chars16 = {'A', 'B', 'C', 0, 'X', 'Y', 'Z'};
        ByteBuffer u = MemoryUtil.memByteBuffer(MemoryUtil.nmemAlloc(chars16.length * 2), chars16.length * 2).order(java.nio.ByteOrder.nativeOrder());
        u.asCharBuffer().put(chars16);
        u.position(0);
        // advance past "ABC\0" (4 chars = 8 bytes)
