        limit = u.position() - 2; // chars, measured in bytes: position after skip = 8, limit = 6
        String u1 = MemoryUtil.memUTF16(u, (limit - 0) >> 1, 0);
        System.out.println("UTF16[0] = " + u1);
        ok &= u1.equals("ABC");
        offset = u.position(); // 8
        String u2 = MemoryUtil.memUTF16(u, (u.remaining()) >> 1, offset);
        System.out.println("UTF16[1] = " + u2);
        ok &= u2.equals("XYZ");
        MemoryUtil.nmemFree(MemoryUtil.memAddress0(u));

        System.out.println(ok ? "ALL TESTS PASSED" : "FAILURES DETECTED");
    }
}
